function varargout = subsref(P,s)
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% varargout = subsref(P,s) indexes a cdopvar object: dot and brace indexing
% are the builtin; paren indexing P(I,J) is the slice of output components
% I and input components J, and indexing after it, P(I,J).C, reads the
% slice.
%
% INPUT
% P:    'cdopvar' object
% s:    substruct of the indexing expression, generated by MATLAB
%
% OUTPUT
% varargout: the slice, the value of a 'dopvar' or 'dopvar2d' field, or
%           what the builtin returns; as many values as the nargout of the
%           caller
%
% NOTES:
% Paren indexing counts COMPONENTS over the concatenated spaces, as for a
% 'dopvar', not blocks: P(I,J) is a container, and a block is P.C{i,j}.
% 'end' and size(P) count components too, while size(P,'block') is the
% block grid. Each run of consecutive indices within one block row (column)
% becomes one block row (column) of the slice.
%
% '.' and '{}' pass the whole chain to the builtin, which dispatches to the
% subsref of the blocks (P.C{i,j}(k,l) slices block (i,j)). The nargout of
% the caller is the builtin count.
%
% A comma list read through a block, {P.C{i,j}.params{:}}, is served by
% the subsref of the block with the same count.
%
% The fields of a 'dopvar' (P, Q1, Q2, R) and of a 'dopvar2d' (R00 to
% R22) are read from a container with that structure (at most one spatial
% variable and R blocks before L2 blocks, or at most two and blocks ordered
% R, L2[x], L2[y], L2[x,y]), P.Q1, P.R.R1, P.R22{2,3}. I, var1, var2 and
% dim are read as for a 'dopvar' if P is opvar-like, and as for a
% 'dopvar2d' otherwise, so dim is 2 x 2 or 4 x 2. A comma list of such a field, P.R22{:}, is not served.
% The first such read of a session warns ('cdopvar:opvarField') that these
% are not fields of the class, and that this support may be dropped in
% future versions.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% PIETOOLS - subsref (cdopvar)
%
% Copyright (C) 2026 PIETOOLS Team
%
% This program is free software; you can redistribute it and/or modify
% it under the terms of the GNU General Public License as published by
% the Free Software Foundation; either version 2 of the License, or
% (at your option) any later version.
%
% This program is distributed in the hope that it will be useful,
% but WITHOUT ANY WARRANTY; without even the implied warranty of
% MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the
% GNU General Public License for more details.
%
% You should have received a copy of the GNU General Public License
% along with this program; if not, write to the Free Software
% Foundation, Inc., 59 Temple Place, Suite 330, Boston, MA  02111-1307  USA
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
% If you modify this code, document all changes carefully and include date
% authorship, and a brief description of modifications
%
% For support, contact M. Peet, Arizona State University at mpeet@asu.edu
%
% Initial coding MMP, 09/29/2026

if strcmp(s(1).type,'()')
    % The component slice P(I,J), or P(I). A comma-list brace after it
    % cannot be served.
    for k = 2:numel(s)
        if strcmp(s(k).type,'{}') && ~all(cellfun(@(x) isscalar(x) && (isnumeric(x) || islogical(x)),s(k).subs))
            error('cdopvar:parenThenList','Slice first, then read the list: Y = P(I,J); Y.field{...}.')
        end
    end
    P = op_slice(P,s(1).subs{:});
    if isscalar(s)
        varargout = {P};
        return
    end
    % Any further indexing, P(I,J).C{1,1}, reads the slice, below.
    s = s(2:end);
end
% Support extracting fields of a 'dopvar' (1D) or 'dopvar2d' (2D), which
% are not actual properties of the class.
f1 = {'P','Q1','Q2','R'};
f2 = {'R00','R0x','R0y','R02','Rx0','Rxx','Rxy','Rx2',...
      'Ry0','Ryx','Ryy','Ry2','R20','R2x','R2y','R22'};
f0 = {'I','var1','var2','dim'};                 % fields of both classes
persistent warned                               % warning below given once
if strcmp(s(1).type,'.') && any(strcmp(s(1).subs,[f0,f1,f2]))
    fname = s(1).subs;
    % One value per field: a comma list would need the count beforehand
    if numel(s)>1 && strcmp(s(2).type,'{}') && ~all(cellfun(@(x) isscalar(x) && isnumeric(x),s(2).subs))
        error('cdopvar:fieldThenList','Read the field first, then the list: R = P.%s; R{:}.',fname)
    end
    % A shared field is read as for a 'dopvar' if P is opvar-like
    if ~any(strcmp(fname,f2)) && is_opvar1d(P)
        val = getfield_opvar1d(P,fname);
    elseif ~any(strcmp(fname,f1)) && is_opvar2d(P)
        val = getfield_opvar2d(P,fname);
    elseif any(strcmp(fname,f1))
        error('cdopvar:notOpvar1d',['''%s'' is a field of a ''dopvar'', but this cdopvar is not opvar-like: '...
            'it needs at most one spatial variable, and R blocks before L2 blocks (see is_opvar1d).'],fname)
    elseif any(strcmp(fname,f2))
        error('cdopvar:notOpvar2d',['''%s'' is a field of a ''dopvar2d'', but this cdopvar is not opvar2d-like: '...
            'it needs at most two spatial variables, and blocks ordered R, L2[x], L2[y], L2[x,y] (see is_opvar2d).'],fname)
    else
        error('cdopvar:notOpvar',['''%s'' is a field of a ''dopvar'' or ''dopvar2d'', but this cdopvar is neither: '...
            'it needs at most two spatial variables, and blocks ordered R, L2[x], L2[y], L2[x,y] (see is_opvar2d).'],fname)
    end
    % Not a property, and this support may be dropped: say so, once per
    % session so that loops over fields are not flooded
    if isempty(warned)
        warned = true;
        warning('cdopvar:opvarField',['A cdopvar has no field ''%s''; it is computed from the blocks as for a ''dopvar'' or ''dopvar2d''. '...
            'Extracting components this way may not be supported in future versions.'],fname)
    end
    if isscalar(s)
        varargout = {val};
    else
        [varargout{1:nargout}] = subsref(val,s(2:end));
    end
    return
end
% The builtin called from this method has the access of the class, so it
% would read protected properties that P.name outside the class may not.
% Raise the error of the builtin for them, same identifier and text.
% Names come from the metaclass, once.
persistent hidden
if ~iscell(hidden)
    mc = ?cdopvar;   pl = mc.PropertyList;
    hidden = {pl(~cellfun(@(a) isequal(a,'public'),{pl.GetAccess})).Name};
end
if strcmp(s(1).type,'.') && any(strcmp(s(1).subs,hidden))
    error(message('MATLAB:class:GetProhibited',s(1).subs,'''cdopvar'''))
end
% Any other indexing: the builtin
[varargout{1:nargout}] = builtin('subsref',P,s);

end
